// ════════════════════════════════════════════════════════════════
// n8n Code node — "Format Response + Analytics"
//
// PURPOSE
//   Receives raw AI Agent2 output. Produces TWO items:
//     [0] response  → consumed by "Send Response to Student2" webhook
//     [1] analytics → consumed by "Analytics Branch (→ Member 4)"
//
// STABLE CONTRACT EMITTED FOR THE PYTHON BACKEND
//   {
//     answer:    str,                                  // markdown, sources stripped
//     sources:   list[{label, url, type:"link"|"file"}],
//     used_tool: bool,
//     response_time_ms: int
//   }
// ════════════════════════════════════════════════════════════════

const validationOutput = $input.first().json;

// ── 1. Extract LLM answer (handle multiple possible shapes) ──
let llmAnswer = '';
if (validationOutput.validated_answer && validationOutput.validated_answer.trim()) {
  llmAnswer = validationOutput.validated_answer;
} else if (validationOutput.output && typeof validationOutput.output === 'string') {
  llmAnswer = validationOutput.output;
} else if (validationOutput.text) {
  llmAnswer = validationOutput.text;
} else {
  try {
    llmAnswer = $('AI Agent2').first().json.output || 'Răspuns indisponibil';
  } catch (e) {
    llmAnswer = 'Răspuns indisponibil';
  }
}
llmAnswer = String(llmAnswer).trim();

// ── 2. Extract sources from the LLM text ──
//
// Format expected from the agent: 📄 **Sursă:** [Label](URL)
// Also tolerates: 📄 Sursa: filename.pdf, 📄 Surse: a.pdf, b.pdf
const sources = [];
const seen = new Set();

const sourceLineRegex = /📄\s*\*{0,2}\s*Surs[aăe]?\s*\*{0,2}\s*:?\s*(.+?)(?:\n|$)/gi;
const markdownLinkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;

for (const match of llmAnswer.matchAll(sourceLineRegex)) {
  const lineContent = match[1].trim();

  // Try markdown links first
  const links = [...lineContent.matchAll(markdownLinkRegex)];

  if (links.length > 0) {
    for (const link of links) {
      const url = link[2].trim();
      const label = link[1].trim() || 'Sursă oficială';
      if (url && !seen.has(url)) {
        seen.add(url);
        sources.push({ label, url, type: 'link' });
      }
    }
  } else {
    // Plain text — could be filename(s) separated by comma/semicolon
    const items = lineContent
      .split(/[,;]/)
      .map(s => s.replace(/\*+/g, '').trim())
      .filter(s => s.length > 2);

    for (const item of items) {
      if (seen.has(item)) continue;
      seen.add(item);
      if (/^https?:\/\//i.test(item)) {
        sources.push({ label: 'Pagină oficială', url: item, type: 'link' });
      } else {
        sources.push({ label: item, url: null, type: 'file' });
      }
    }
  }
}

// ── 3. Strip source lines from the answer to avoid duplication in UI ──
const cleanAnswer = llmAnswer
  .replace(sourceLineRegex, '')
  .trim()
  .replace(/\n{3,}/g, '\n\n');

// ── 4. Metadata ──
const startTime = $('Parse Request2').first().json.start_time;
const responseTime = Date.now() - startTime;
const query = $('Parse Request2').first().json.query;
const sessionId = $('Parse Request2').first().json.session_id;
const usedTool = sources.length > 0;

const crypto = require('crypto');
const queryHash = crypto
  .createHash('sha256')
  .update(query.toLowerCase().trim())
  .digest('hex');

// ── 5. Outputs ──
return [
  {
    json: {
      type: 'response',
      answer: cleanAnswer,
      sources: sources,
      used_tool: usedTool,
      response_time_ms: responseTime,
    },
  },
  {
    json: {
      type: 'analytics',
      query_hash: queryHash,
      category: 'ACADEMIC',
      used_tool: usedTool,
      response_ms: responseTime,
      docs_matched: sources.map(s => s.url || s.label),
      was_answered: true,
      session_id: sessionId,
      created_at: new Date().toISOString(),
    },
  },
];

// ANALYTICS BRANCH (Async — does not block response)
// This data goes to Member 4's PostgreSQL logging workflow
return [$input.first()];

const inputJson = $input.first().json;
let body = inputJson.body || inputJson;

if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}

const query = String(body.query || body.message || '').trim();
const sessionId = String(body.session_id || 'anonymous');

if (!query || query.length < 1) {
  return [{
    json: {
      query: '',
      chatInput: '',
      session_id: sessionId,
      start_time: Date.now(),
      is_empty: true
    }
  }];
}

return [{
  json: {
    query: query,
    chatInput: query,
    query_original: query,
    session_id: sessionId,
    start_time: Date.now(),
    is_empty: false
  }
}];
